from pathlib import Path
import struct
for f in sorted(Path('tests/fuzz/fuzz_binary_message_corpus/generated').iterdir()):
    data=f.read_bytes(); off=0; chunks=[]
    while off+8<=len(data):
        typ=data[off:off+3].decode('latin1'); final=chr(data[off+3]); size=struct.unpack_from('<I',data,off+4)[0]
        if size<8 or off+size>len(data):
            chunks.append((typ,final,size,'bad')); break
        bodyoff=off+8
        sid=None
        if typ=='MSG':
            svc=bodyoff+4+4+8
            if svc<len(data):
                enc=data[svc]
                if enc==1 and svc+4<=off+size:
                    sid=struct.unpack_from('<H',data,svc+2)[0]
                elif enc==0 and svc+2<=off+size:
                    sid=data[svc+1]
                elif enc==2 and svc+7<=off+size:
                    sid=struct.unpack_from('<I',data,svc+3)[0]
        elif typ=='OPN':
            # channel id + asym sec header policy string len, cert len, thumb len; skip simplistic search nodeid after seq
            pass
        chunks.append((typ,final,size,sid))
        off+=size
    print(f.name,len(data),chunks)
